-- PostgreSQL reference schema; Flask local demo creates compatible tables through SQLAlchemy.
CREATE TABLE users (user_id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, email VARCHAR(254) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role VARCHAR(10) NOT NULL CHECK (role IN ('student','staff','admin')), first_name VARCHAR(80) NOT NULL, last_name VARCHAR(80) NOT NULL, is_active BOOLEAN NOT NULL DEFAULT true, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE courses (course_id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, course_code VARCHAR(20) NOT NULL UNIQUE, course_name VARCHAR(120) NOT NULL, description TEXT, staff_id BIGINT NOT NULL REFERENCES users(user_id) ON DELETE RESTRICT, credits SMALLINT NOT NULL CHECK (credits BETWEEN 1 AND 10), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE enrollments (enrollment_id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users(user_id) ON DELETE CASCADE, course_id BIGINT NOT NULL REFERENCES courses(course_id) ON DELETE CASCADE, status VARCHAR(12) NOT NULL DEFAULT 'active' CHECK (status IN ('active','withdrawn')), enrolled_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(user_id,course_id));
CREATE TABLE deadlines (deadline_id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, course_id BIGINT NOT NULL REFERENCES courses(course_id) ON DELETE CASCADE, title VARCHAR(160) NOT NULL, description TEXT, due_at TIMESTAMPTZ NOT NULL, max_marks INTEGER NOT NULL CHECK(max_marks>0), created_by BIGINT NOT NULL REFERENCES users(user_id) ON DELETE RESTRICT, is_active BOOLEAN NOT NULL DEFAULT true, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE submissions (submission_id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, deadline_id BIGINT NOT NULL REFERENCES deadlines(deadline_id) ON DELETE CASCADE, user_id BIGINT NOT NULL REFERENCES users(user_id) ON DELETE CASCADE, submitted_at TIMESTAMPTZ NOT NULL DEFAULT now(), object_key TEXT, file_name VARCHAR(255), note TEXT, status VARCHAR(12) NOT NULL CHECK(status IN ('submitted','late','graded')), marks_obtained INTEGER CHECK(marks_obtained IS NULL OR marks_obtained>=0), feedback TEXT, graded_by BIGINT REFERENCES users(user_id) ON DELETE SET NULL, UNIQUE(deadline_id,user_id));
CREATE TABLE notifications (notification_id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users(user_id) ON DELETE CASCADE, deadline_id BIGINT REFERENCES deadlines(deadline_id) ON DELETE SET NULL, message VARCHAR(500) NOT NULL, type VARCHAR(30) NOT NULL, is_read BOOLEAN NOT NULL DEFAULT false, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE activity_logs (log_id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, user_id BIGINT REFERENCES users(user_id) ON DELETE SET NULL, action VARCHAR(80) NOT NULL, entity_type VARCHAR(50) NOT NULL, entity_id BIGINT, occurred_at TIMESTAMPTZ NOT NULL DEFAULT now(), ip_address INET);
-- Student-owned planning items are intentionally separate from instructor deadlines.
CREATE TABLE personal_tasks (task_id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users(user_id) ON DELETE CASCADE, title VARCHAR(160) NOT NULL, description VARCHAR(2000), due_at TIMESTAMPTZ NOT NULL, priority VARCHAR(10) NOT NULL DEFAULT 'medium' CHECK(priority IN ('low','medium','high')), recurrence VARCHAR(10) NOT NULL DEFAULT 'none' CHECK(recurrence IN ('none','weekly','monthly')), is_complete BOOLEAN NOT NULL DEFAULT false, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE task_subtasks (subtask_id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, task_id BIGINT NOT NULL REFERENCES personal_tasks(task_id) ON DELETE CASCADE, title VARCHAR(160) NOT NULL, is_complete BOOLEAN NOT NULL DEFAULT false, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE announcements (announcement_id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, course_id BIGINT NOT NULL REFERENCES courses(course_id) ON DELETE CASCADE, author_id BIGINT NOT NULL REFERENCES users(user_id) ON DELETE RESTRICT, title VARCHAR(160) NOT NULL, body VARCHAR(4000) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE reminder_logs (reminder_id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users(user_id) ON DELETE CASCADE, source_type VARCHAR(20) NOT NULL, source_id BIGINT NOT NULL, sent_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(user_id,source_type,source_id));
